/**
 * Performance test data: a separate database (never UAT or production) filled with
 * synthetic data at a multiple of today's volume (scale 1 = 120 buildings, 600
 * landlords), then the Rent Schedule generated by the application itself.
 *
 *   node scripts/perf/seed.js --scale=3 [--db=sd_rent_perf_3x] [--from=01/04/2024 --to=31/03/2031]
 *
 * Per landlord: 1.2 SD records (some landlords hold two), SD transactions, one Rent
 * Code with an Office + Maintenance + Car Park agreement, three yearly 5% RCD
 * escalations, a two-month rent-free waiver and audit history. Users perf01..perf20
 * (password Perf@12345) are created for the load test.
 */
const path = require('path');
require('dotenv').config({ path: path.join(__dirname, '..', '..', '.env') });

const arg = (name, fallback) => {
  const m = process.argv.find((a) => a.startsWith(`--${name}=`));
  return m ? m.split('=').slice(1).join('=') : fallback;
};
const SCALE = Number(arg('scale', '3'));
const DB = arg('db', `sd_rent_perf_${SCALE}x`);
if (!/^sd_rent_perf_/.test(DB)) throw new Error('The performance database name must start with sd_rent_perf_ (it is dropped and re-created).');
const FROM = arg('from', '01/04/2024');
const TO = arg('to', '31/03/2031');

const BUILDINGS = Math.round(120 * SCALE);
const LANDLORDS = Math.round(600 * SCALE);
const SDS = Math.round(LANDLORDS * 1.2);

process.env.DB_NAME = DB;           // before any application module loads
process.env.EMAIL_DRY_RUN = 'true';

const { Client } = require('pg');
const bcrypt = require('bcryptjs');

const t0 = Date.now();
const step = (label) => console.log(`[${((Date.now() - t0) / 1000).toFixed(1)}s] ${label}`);

async function recreate() {
  const c = new Client({
    user: process.env.DB_USER, password: process.env.DB_PASSWORD, host: process.env.DB_HOST,
    port: parseInt(process.env.DB_PORT, 10) || 5432, database: 'postgres',
  });
  await c.connect();
  await c.query(`DROP DATABASE IF EXISTS "${DB}" WITH (FORCE)`);
  await c.query(`CREATE DATABASE "${DB}"`);
  await c.end();
}

async function main() {
  console.log(`Scale ${SCALE}x -> ${BUILDINGS} buildings, ${LANDLORDS} landlords, ${SDS} SD records; database ${DB}`);
  await recreate();
  const { pool } = require('../../config/db');
  const { runMigrations } = require('../migrate');
  await runMigrations(pool, { log: () => {} });
  step('database created and migrated');

  const q = (sql, params) => pool.query(sql, params);
  // Locations: 5 regions, 25 cities, one site per building; one cost center per building
  await q(`INSERT INTO location_l1 (l1_name, created_by) SELECT 'Region ' || g, 'perf' FROM generate_series(1, 5) g`);
  await q(`INSERT INTO location_l2 (l2_name, l1_id, created_by)
           SELECT 'City ' || g, (SELECT MIN(l1_id) FROM location_l1) + (g % 5), 'perf' FROM generate_series(1, 25) g`);
  await q(`INSERT INTO location_l3 (l3_name, l1_id, l2_id, created_by)
           SELECT 'Site ' || g, l2.l1_id, l2.l2_id, 'perf'
           FROM generate_series(1, $1::int) g JOIN location_l2 l2 ON l2.l2_id = (SELECT MIN(l2_id) FROM location_l2) + (g % 25)`, [BUILDINGS]);
  await q(`INSERT INTO cost_centers (cost_center_code, cost_center_name, created_by)
           SELECT 'PCC' || lpad(g::text, 4, '0'), 'Building ' || lpad(g::text, 4, '0'), 'perf' FROM generate_series(1, $1::int) g`, [BUILDINGS]);
  step('locations and cost centers');

  // SD records: building g % B, landlord g % L, 12 floors, lease of 9 years starting 2018-2026
  await q(`
    WITH cc AS (SELECT cost_center_id, row_number() OVER (ORDER BY cost_center_id) - 1 AS n FROM cost_centers),
         l3 AS (SELECT l3_id, l2_id, l1_id, row_number() OVER (ORDER BY l3_id) - 1 AS n FROM location_l3),
         s AS (SELECT g, date '2018-01-01' + ((g * 37) % 3100) AS lcd FROM generate_series(1, $1::int) g)
    INSERT INTO sd_master (lease_id, agreement_no, cost_center_id, l1_id, l2_id, l3_id, landlord_name, landlord_status, building_status,
                           floor, agreement_value, lease_commencement_date, rent_commencement_date, lease_end_date, created_by)
    SELECT 'LS' || s.g, 'AG' || s.g, cc.cost_center_id, l3.l1_id, l3.l2_id, l3.l3_id,
           'Landlord ' || lpad(((s.g - 1) % $3::int + 1)::text, 5, '0') || ' Properties Private Limited',
           CASE WHEN s.g % 20 = 0 THEN 'Passive' ELSE 'Active' END, 'Active',
           ((s.g % 12) + 1) || 'F', 300000 + (s.g * 7919) % 2700000,
           s.lcd, s.lcd + 60, (s.lcd + interval '9 years')::date, 'perf'
    FROM s JOIN cc ON cc.n = s.g % $2::int JOIN l3 ON l3.n = s.g % $2::int`, [SDS, BUILDINGS, LANDLORDS]);
  step(`${SDS} SD records`);

  // SD transactions: three payments, then a transfer, adjustment or refund for some
  await q(`
    WITH t AS (
      SELECT s.sd_id, k, s.lease_commencement_date + k * 45 AS d, s.agreement_value
      FROM sd_master s CROSS JOIN generate_series(1, 5) k
      WHERE k <= 3 OR (k = 4 AND s.sd_id % 4 = 0) OR (k = 5 AND s.sd_id % 6 = 0))
    INSERT INTO sd_transactions (sd_id, sd_type, fy, txn_date, agreement_status, paid_amount, transfer_amount, adjustment_amount, refund_amount, remarks, created_by)
    SELECT sd_id, CASE WHEN k = 3 AND sd_id % 3 = 0 THEN 'CAM SD' ELSE 'Landlord SD' END,
           CASE WHEN extract(month FROM d) >= 4 THEN extract(year FROM d)::int || '-' || (extract(year FROM d)::int + 1)
                ELSE (extract(year FROM d)::int - 1) || '-' || extract(year FROM d)::int END,
           d, CASE WHEN k = 1 THEN 'LOI' ELSE 'Agreement' END,
           CASE WHEN k <= 3 THEN trunc(agreement_value / 3, 2) ELSE 0 END,
           CASE WHEN k = 4 THEN 10000 ELSE 0 END, CASE WHEN k = 5 THEN 5000 ELSE 0 END, 0,
           'Perf test entry ' || k, 'perf'
    FROM t`);
  step('SD transactions');

  // Rent Master: one Rent Code per SD record
  await q(`
    INSERT INTO rent_master (sd_id, landlord_name, ll_status, business_key, created_by)
    SELECT s.sd_id, s.landlord_name, 'Active',
           upper(cc.cost_center_name || ' | ' || s.sd_code || ' | ' || s.floor || ' | ' || s.landlord_name), 'perf'
    FROM sd_master s JOIN cost_centers cc ON cc.cost_center_id = s.cost_center_id ORDER BY s.sd_id`);
  await q(`INSERT INTO rent_agreements (rent_id, agreement_status, status, created_by)
           SELECT rent_id, 'Individual', 'Active', 'perf' FROM rent_master ORDER BY rent_id`);
  // Office (Sq.Ft x Rate), Maintenance (Sq.Ft x 12, from the LCD), Car Park (No. x 3,000)
  await q(`
    INSERT INTO rent_agreement_components (agreement_id, component_code, quantity, rate, percentage)
    SELECT a.agreement_id, c.code, c.qty, c.rate, 100
    FROM rent_agreements a
    CROSS JOIN LATERAL (VALUES
      ('OFFICE', 8000 + (a.agreement_id * 13) % 24000, 55 + (a.agreement_id % 40)),
      ('MAINTENANCE', 8000 + (a.agreement_id * 13) % 24000, 8),
      ('CAR_PARK', 10 + (a.agreement_id % 40), 2500)) AS c(code, qty, rate)`);
  // Three yearly 5% escalations from the RCD; a two-month rent-free waiver
  await q(`
    INSERT INTO rent_rules (rent_id, rule_type, escalation_months, percentage, status, effective_date, created_by)
    SELECT r.rent_id, 'RCD', 12, 5, 'Active', (s.rent_commencement_date + make_interval(months => 12 * k))::date, 'perf'
    FROM rent_master r JOIN sd_master s ON s.sd_id = r.sd_id CROSS JOIN generate_series(1, 3) k ORDER BY r.rent_id, k`);
  await q(`
    INSERT INTO rent_waivers (rent_id, from_date, to_date, waiver_status, remark, created_by)
    SELECT r.rent_id, s.rent_commencement_date, (s.rent_commencement_date + interval '2 months' - interval '1 day')::date, 'Yes', 'Rent-free fit-out period', 'perf'
    FROM rent_master r JOIN sd_master s ON s.sd_id = r.sd_id`);
  step('Rent Master, agreements, rules, waivers');

  // Audit history: 40 entries per SD record
  await q(`INSERT INTO audit_log (table_name, record_id, action, action_by, action_date, details)
           SELECT 'sd_master', s.sd_id, 'UPDATE', 'perf' || lpad((k % 20 + 1)::text, 2, '0'), now() - make_interval(days => k * 9), 'Perf history ' || k
           FROM sd_master s CROSS JOIN generate_series(1, 40) k`);
  // Users for the load test
  const hash = await bcrypt.hash('Perf@12345', 10);
  await q(`INSERT INTO users (user_name, user_email, password_hash, status, is_admin, created_by)
           SELECT 'perf' || lpad(g::text, 2, '0'), 'perf' || g || '@example.test', $1, 'Active', TRUE, 'perf' FROM generate_series(1, 20) g`, [hash]);
  step('audit history and 20 users');

  // Rent Schedule through the application's own generator (timed)
  const schedule = require('../../services/rentScheduleService');
  const { parseDMY } = require('../../utils/dates');
  const g0 = Date.now();
  const res = await schedule.generate({ fromDate: parseDMY(FROM), toDate: parseDMY(TO), filters: {}, by: 'perf' });
  const genSeconds = (Date.now() - g0) / 1000;
  step(`Rent Schedule generated ${FROM} to ${TO}: ${res.lines} lines for ${res.rentCodes} Rent Codes in ${genSeconds.toFixed(1)}s`);

  await q('VACUUM ANALYZE');
  const counts = (await q(`SELECT
      (SELECT COUNT(*) FROM cost_centers)::int AS buildings, (SELECT COUNT(DISTINCT landlord_name) FROM sd_master)::int AS landlords,
      (SELECT COUNT(*) FROM sd_master)::int AS sd_records, (SELECT COUNT(*) FROM sd_transactions)::int AS sd_transactions,
      (SELECT COUNT(*) FROM rent_master)::int AS rent_codes, (SELECT COUNT(*) FROM rent_rules)::int AS rules,
      (SELECT COUNT(*) FROM rent_schedule_lines)::int AS schedule_lines, (SELECT COUNT(*) FROM audit_log)::int AS audit_rows,
      (SELECT round(SUM(final_amount) / 12 / 1e7, 2) FROM rent_schedule_lines WHERE rent_month BETWEEN '2025-04-01' AND '2026-03-01') AS rent_per_month_crore_fy2526,
      pg_size_pretty(pg_database_size(current_database())) AS db_size`)).rows[0];
  console.log(JSON.stringify({ scale: SCALE, db: DB, ...counts, schedule_generate_seconds: genSeconds }, null, 2));
  await pool.end();
}

main().catch((err) => { console.error(err); process.exit(1); });
